htmlTemplate.css:
:root {
  --navy: #002f6d;
  --band-gray-bg: #d1d5db;
  --band-gray-text: #111827;
  --body-text: #111827;
  --muted: #9CA3AF;
  --alt-row: #F4F6FA;
  --gold: #e0a800;
}
* { box-sizing: border-box; }
body { font-family: Helvetica, Arial, sans-serif; font-size: 8pt; color: var(--body-text); }
.header { display: flex; flex-direction: row; justify-content: space-between; align-items: flex-start; }
.header-logo { width: 96pt; flex: 0 0 96pt; }
.logo-img { width: 96pt; height: 30pt; object-fit: contain; }
.header-center { flex: 1; text-align: center; }
.project-title { font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold; font-size: 13pt; }
.header-sub { font-size: 8pt; color: #374151; margin-top: 2pt; }
.header-right { text-align: right; width: 150pt; }
.header-right-bold { font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold; font-size: 10pt; }
.header-right-sm { font-size: 7.5pt; color: #374151; margin-top: 1pt; }
.rule { border-bottom: 1.5pt solid var(--navy); margin: 4pt 0 6pt; }
.cols { display: flex; flex-direction: row; gap: 10pt; }
.left-col { width: 250pt; }
.right-col { flex: 1; }
.box { border: 0.5pt solid var(--muted); margin-bottom: 5pt; break-inside: avoid; }
.band { background: var(--navy); color: #fff; font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold; font-size: 9pt; padding: 2pt 6pt; line-height: 1.15; display: flex; flex-direction: row; justify-content: space-between; }
.kv { display: flex; flex-direction: row; justify-content: space-between; padding: 1.4pt 6pt; line-height: 1.15; border-bottom: 0.5pt solid #e5e7eb; font-size: 8.5pt; }
.kv:last-child { border-bottom: none; }
.kv-value { font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold; }
.std-table { width: 100%; border-collapse: collapse; font-size: 8.5pt; break-inside: avoid; }
.std-table th { background: #eef2f8; font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold; padding: 1.8pt 5pt; text-align: left; line-height: 1.15; }
.std-table th.r, .std-table td.r { text-align: right; }
.std-table td { padding: 1.4pt 5pt; border-bottom: 0.5pt solid #e5e7eb; line-height: 1.15; }
.std-table tr.total td { background: #f3f4f6; font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold; border-top: 0.5pt solid var(--muted); }
.section-band { break-after: avoid; break-inside: avoid; background: var(--navy); color: #fff; font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold; font-size: 10pt; padding: 2pt 8pt; line-height: 1.15; margin-top: 6pt; margin-bottom: 2pt; }
.chart-caption { font-size: 7pt; color: #6b7280; text-align: center; margin-top: 2pt; break-before: avoid; }
.foot-note { font-size: 7pt; color: var(--muted); margin-top: 8pt; }
.empty-note { font-size: 8.5pt; color: var(--muted); font-style: italic; padding: 3pt 5pt; }
.delay-columns { display: flex; flex-direction: row; gap: 10pt; break-inside: avoid; }
.delay-col { flex: 1; }
.delay-row { display: flex; flex-direction: row; align-items: center; gap: 5pt; padding: 0.8pt 0; break-inside: avoid; }
.delay-row .delay-label { flex: 0 0 92pt; font-size: 8pt; color: var(--body-text); }
.delay-row .delay-track { flex: 1; height: 6pt; background: #eef2f8; border-radius: 1pt; overflow: hidden; }
.delay-row .delay-bar { display: block; height: 100%; background: var(--navy); }
.delay-row .delay-hours { flex: 0 0 30pt; text-align: right; font-size: 8pt; font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold; }
.delay-row .delay-pct { flex: 0 0 26pt; text-align: right; font-size: 7pt; color: var(--muted); }
.delay-total-row { padding-top: 3pt; margin-top: 3pt; border-top: 0.5pt solid var(--navy); }
.delay-total-row .delay-label { font-family: Helvetica-Bold, Helvetica, Arial, sans-serif; font-weight: bold; font-size: 8.5pt; }
.delay-total-row .delay-hours { font-size: 8.5pt; }
